CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(255) NOT NULL, phone_number VARCHAR(20), role VARCHAR(20) NOT NULL DEFAULT 'customer', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash VARCHAR(255), expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_sessions_user ON user_sessions(user_id); CREATE INDEX IF NOT EXISTS idx_sessions_expires ON user_sessions(expires_at);
CREATE TABLE IF NOT EXISTS supplier_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, business_name VARCHAR(255) NOT NULL, business_address TEXT, business_phone VARCHAR(20), verification_status VARCHAR(50) NOT NULL DEFAULT 'pending', verification_doc_url TEXT, verified_at TIMESTAMP, verified_by UUID REFERENCES users(id), rejection_reason TEXT, created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(100) UNIQUE NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id UUID NOT NULL REFERENCES supplier_profiles(id) ON DELETE CASCADE, name VARCHAR(255) NOT NULL, description TEXT, price NUMERIC(12,2) NOT NULL CHECK(price >= 0), stock_quantity INT NOT NULL DEFAULT 0 CHECK(stock_quantity >= 0), category_id UUID NOT NULL REFERENCES categories(id), image_url TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS carts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS cart_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cart_id UUID NOT NULL REFERENCES carts(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), quantity INT NOT NULL CHECK(quantity > 0), UNIQUE(cart_id, product_id));
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES users(id), order_number VARCHAR(50) UNIQUE NOT NULL, status VARCHAR(50) NOT NULL DEFAULT 'pending', total_amount NUMERIC(12,2) NOT NULL, delivery_name VARCHAR(255) NOT NULL, delivery_address TEXT NOT NULL, delivery_phone VARCHAR(20) NOT NULL, payment_reference VARCHAR(255), payment_verified_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), supplier_id UUID NOT NULL REFERENCES supplier_profiles(id), quantity INT NOT NULL CHECK(quantity > 0), unit_price NUMERIC(12,2) NOT NULL, subtotal NUMERIC(12,2) NOT NULL, supplier_order_status VARCHAR(50) NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT NOW(), updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payment_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id), payment_reference VARCHAR(255), amount NUMERIC(12,2), status VARCHAR(50), paystack_response JSONB, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS stock_adjustments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID REFERENCES orders(id) ON DELETE SET NULL, product_id UUID NOT NULL REFERENCES products(id), supplier_id UUID NOT NULL REFERENCES supplier_profiles(id), quantity INT NOT NULL, reason VARCHAR(30) NOT NULL, stock_after INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT NOW());
ALTER TABLE stock_adjustments ADD COLUMN IF NOT EXISTS order_id UUID REFERENCES orders(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS contact_submissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(255), email VARCHAR(255), message TEXT, status VARCHAR(50) NOT NULL DEFAULT 'received', created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id); CREATE INDEX IF NOT EXISTS idx_products_active ON products(is_active); CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id); CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);
INSERT INTO categories (name) VALUES ('Vegetables'),('Fruits'),('Dairy'),('Grains'),('Meat'),('Seafood'),('Beverages'),('Pantry') ON CONFLICT (name) DO NOTHING;
